#!/usr/bin/env bash
# Generated by scripts/crosscode/smilei.jl. Runs inside the Smilei GPU container with the run
# directory at /run-dir (PM_RUN_DIR) and the worktree read-only at /worktree; one Smilei run
# per seed, in turn, each in its seed-<seed>/ subdirectory. Seeds that finished in an earlier
# job are skipped; no new seed starts after 6600 s of this job.
set -euo pipefail
top="${PM_RUN_DIR:-/run-dir}"
export OMP_NUM_THREADS=1
export OMP_SCHEDULE=dynamic
mpi_env="${PM_MPI_ENV:-/opt/smilei/mpi_env.sh}"
. "$mpi_env"
pm-versions > "$top/versions.toml"
job_start=$(date +%s)
budget=6600
remaining=""
for seed in 20261031 20262031 20263031 20264031 20265031 20266031 20267031 20268031 20269031 20270031 20271031 20272031 20273031 20274031 20275031 20276031 20277031 20278031 20279031 20280031 20281031 20282031 20283031 20284031 20285031 20286031 20287031 20288031 20289031 20290031 20291031 20292031; do
  cd "$top/seed-$seed"
  grep -q '^# end:' container.txt 2>/dev/null && continue
  if [ -n "$budget" ] && [ $(( $(date +%s) - job_start )) -ge "$budget" ]; then
    remaining="$remaining $seed"; continue
  fi
  {
    echo "# build: gpu"
    echo "# smilei binary: $(command -v smilei)"
    echo "# smilei version: $(cat /opt/smilei/VERSION 2>/dev/null || echo unknown)"
    echo "# threads: $OMP_NUM_THREADS, cpus: $(nproc)"
    echo "# cpu model: $(grep -m1 'model name' /proc/cpuinfo | cut -d: -f2- | sed 's/^ *//')"
    echo "# patches: 1x1"
    echo "# fastmath: yes"
    echo "# mpi: $(grep -h '^export ' "$mpi_env" | sed 's/^export //' | paste -sd ' ' -)"
    echo "# gpu: $(nvidia-smi --query-gpu=name,driver_version --format=csv,noheader 2>/dev/null | paste -sd ';' - || echo unknown)"
    echo "# gpu before: $(nvidia-smi --query-gpu=utilization.gpu,memory.used --format=csv,noheader 2>/dev/null | paste -sd ';' - || echo unknown)"
    echo "# gpu processes before: $(nvidia-smi --query-compute-apps=pid,process_name,used_memory --format=csv,noheader 2>/dev/null | paste -sd ';' - || echo unknown)"
    echo "# seed: $seed"
  } > container.txt
  echo "# start: $(date -u +%Y-%m-%dT%H:%M:%S.%NZ)" >> container.txt
  smilei namelist.py > smilei.log 2>&1
  echo "# end: $(date -u +%Y-%m-%dT%H:%M:%S.%NZ)" >> container.txt
  echo "# gpu after: $(nvidia-smi --query-gpu=utilization.gpu,memory.used --format=csv,noheader 2>/dev/null | paste -sd ';' - || echo unknown)" >> container.txt
done
if [ -n "$remaining" ]; then echo "# seeds remaining after the budget:$remaining"; else echo "# all seeds done"; fi
